module tb_TopModule;
    logic [2:0] a;
    logic [2:0] b;
    logic [2:0] out_or_bitwise;
    logic       out_or_logical;
    logic [5:0] out_not;

    TopModule dut (
        .a(a),
        .b(b),
        .out_or_bitwise(out_or_bitwise),
        .out_or_logical(out_or_logical),
        .out_not(out_not)
    );

    initial begin
        int i, j;
        logic [2:0] exp_bitwise;
        logic       exp_logical;
        logic [5:0] exp_not;

        for (i = 0; i < 8; i++) begin
            for (j = 0; j < 8; j++) begin
                a = i[2:0];
                b = j[2:0];
                #1;
                exp_bitwise = a | b;
                exp_logical = (a != 3'd0) || (b != 3'd0);
                exp_not = {~b, ~a};

                if (out_or_bitwise !== exp_bitwise ||
                    out_or_logical !== exp_logical ||
                    out_not !== exp_not) begin
                    $display("SELFFAIL: a=%b b=%b | got: bitwise=%b, logical=%b, not=%b | exp: bitwise=%b, logical=%b, not=%b",
                             a, b, out_or_bitwise, out_or_logical, out_not,
                             exp_bitwise, exp_logical, exp_not);
                    $finish;
                end
            end
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
